from collections import deque


class Codec:
    def serialize(self, root):
        out = []
        queue = deque([root])
        while queue:
            node = queue.popleft()
            if node is None:
                out.append("null")
                continue
            out.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
        return ",".join(out)

    def deserialize(self, data):
        parts = data.split(",")
        if parts[0] == "null":
            return None
        root = TreeNode(int(parts[0]))
        queue = deque([root])
        i = 1
        while queue:
            node = queue.popleft()
            if parts[i] != "null":
                node.left = TreeNode(int(parts[i]))
                queue.append(node.left)
            i += 1
            if parts[i] != "null":
                node.right = TreeNode(int(parts[i]))
                queue.append(node.right)
            i += 1
        return root

class Codec {
    String serialize(TreeNode root) {
        List<String> out = new ArrayList<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) { out.add("null"); continue; }
            out.add(String.valueOf(node.val));
            queue.add(node.left);
            queue.add(node.right);
        }
        return String.join(",", out);
    }

    TreeNode deserialize(String data) {
        String[] parts = data.split(",");
        if (parts[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(parts[0]));
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (!parts[i].equals("null")) { node.left = new TreeNode(Integer.parseInt(parts[i])); queue.add(node.left); }
            i++;
            if (!parts[i].equals("null")) { node.right = new TreeNode(Integer.parseInt(parts[i])); queue.add(node.right); }
            i++;
        }
        return root;
    }
}

class Codec {
public:
    string serialize(TreeNode* root) {
        string out;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            if (!out.empty()) out += ",";
            if (node == nullptr) { out += "null"; continue; }
            out += to_string(node->val);
            q.push(node->left);
            q.push(node->right);
        }
        return out;
    }

    TreeNode* deserialize(string data) {
        vector<string> parts;
        stringstream ss(data);
        string part;
        while (getline(ss, part, ',')) parts.push_back(part);
        if (parts[0] == "null") return nullptr;
        TreeNode* root = new TreeNode(stoi(parts[0]));
        queue<TreeNode*> q;
        q.push(root);
        size_t i = 1;
        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            if (parts[i] != "null") { node->left = new TreeNode(stoi(parts[i])); q.push(node->left); }
            i++;
            if (parts[i] != "null") { node->right = new TreeNode(stoi(parts[i])); q.push(node->right); }
            i++;
        }
        return root;
    }
};

class Codec {
  serialize(root) {
    const out = [];
    const preorder = (node) => {
      if (node === null) return;
      out.push(node.val);                  // node, then left, then right
      preorder(node.left);
      preorder(node.right);
    };
    preorder(root);
    return out.join(",");
  }

  deserialize(data) {
    const values = data === "" ? [] : data.split(",").map(Number);
    let i = 0;
    const build = (low, high) => {         // the next subtree: values between low and high
      if (i === values.length || values[i] < low || values[i] > high) return null;
      const node = new TreeNode(values[i++]);
      node.left = build(low, node.val);
      node.right = build(node.val, high);
      return node;
    };
    return build(-Infinity, Infinity);
  }
}

class Codec:
    def serialize(self, root):
        out = []

        def preorder(node):
            if node is None:
                return
            out.append(str(node.val))     # node, then left, then right
            preorder(node.left)
            preorder(node.right)

        preorder(root)
        return ",".join(out)

    def deserialize(self, data):
        values = [int(x) for x in data.split(",")] if data else []
        i = 0

        def build(low, high):             # the next subtree: values between low and high
            nonlocal i
            if i == len(values) or not low <= values[i] <= high:
                return None
            node = TreeNode(values[i])
            i += 1
            node.left = build(low, node.val)
            node.right = build(node.val, high)
            return node

        return build(float("-inf"), float("inf"))

class Codec {
    private int i;

    String serialize(TreeNode root) {
        StringBuilder out = new StringBuilder();
        preorder(root, out);
        return out.toString();
    }

    private void preorder(TreeNode node, StringBuilder out) {
        if (node == null) return;
        if (out.length() > 0) out.append(',');
        out.append(node.val);                        // node, then left, then right
        preorder(node.left, out);
        preorder(node.right, out);
    }

    TreeNode deserialize(String data) {
        if (data.isEmpty()) return null;
        String[] parts = data.split(",");
        int[] values = new int[parts.length];
        for (int k = 0; k < parts.length; k++) values[k] = Integer.parseInt(parts[k]);
        i = 0;
        return build(values, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private TreeNode build(int[] values, long low, long high) {   // values between low and high
        if (i == values.length || values[i] < low || values[i] > high) return null;
        TreeNode node = new TreeNode(values[i++]);
        node.left = build(values, low, node.val);
        node.right = build(values, node.val, high);
        return node;
    }
}

class Codec {
    void preorder(TreeNode* node, string& out) {
        if (node == nullptr) return;
        if (!out.empty()) out += ",";
        out += to_string(node->val);                 // node, then left, then right
        preorder(node->left, out);
        preorder(node->right, out);
    }

    TreeNode* build(vector<int>& values, size_t& i, long long low, long long high) {
        if (i == values.size() || values[i] < low || values[i] > high) return nullptr;
        TreeNode* node = new TreeNode(values[i++]);
        node->left = build(values, i, low, node->val);
        node->right = build(values, i, node->val, high);
        return node;
    }

public:
    string serialize(TreeNode* root) {
        string out;
        preorder(root, out);
        return out;
    }

    TreeNode* deserialize(string data) {
        vector<int> values;
        stringstream ss(data);
        string part;
        while (getline(ss, part, ',')) values.push_back(stoi(part));
        size_t i = 0;
        return build(values, i, LLONG_MIN, LLONG_MAX);
    }
};
